#!/usr/bin/env node
'use strict';

// Build (or capture) the sprint-1 system the /sprint delta route runs against.
//
// The delta route needs a real, built, green sprint-1 product to amend: a
// hand-written stand-in would test the route against something the harness
// never produced. So the baseline is generated by the harness itself, once,
// and committed — the route then seeds from it in seconds instead of paying
// for a full sprint-1 build on every run.
//
// Product only. The harness control plane (.claude/, CLAUDE.md, the scaffold's
// own docs, project-manifest.json) is deliberately NOT captured, so the route
// exercises the CURRENT harness against a sprint-1 product rather than a frozen
// copy of an old harness. The route reinstalls it with `/scaffold --yes existing`.
//
//   node test/e2e/make-sprint1-baseline.js                  # live build, then snapshot
//   node test/e2e/make-sprint1-baseline.js --from <dir>     # snapshot an already-built project
//   node test/e2e/make-sprint1-baseline.js --snapshot-only  # snapshot the last live workdir

const fs = require('fs');
const path = require('path');
const { randomUUID } = require('crypto');
const { execFileSync } = require('child_process');

const { runClaude } = require('./helpers/claude-runner');
const { e2eWorkdir } = require('./helpers/e2e-workdir');
const { freshProject } = require('./helpers/fresh-project');
const { runManifestSuite } = require('./helpers/manifest-suite');
const { resolvePrd, spineGap } = require('./helpers/prd-fixture');
const { billRoute, formatBill, writeBaseline } = require('./helpers/phase-budget');

const BUILD_DIR = e2eWorkdir('sprint1-baseline');
const OUT_DIR = path.join(__dirname, 'fixtures', 'baselines', 'shortlink-sprint1');
const PLUGIN_DIR = path.join(__dirname, '..', '..', '.claude');

// Dependency trees, build output, VCS, and the harness control plane.
const EXCLUDED = new Set([
  'node_modules', '.git', '.venv', 'venv', '__pycache__', '.pytest_cache', '.mypy_cache',
  '.ruff_cache', 'dist', 'build', '.next', '.turbo', 'coverage', 'htmlcov', '.DS_Store',
  '.claude', 'CLAUDE.md', 'SCAFFOLD_README.md', 'CODEBASE_MAP.md', 'design.md',
  'init.sh', 'project-manifest.json', 'claude-progress.txt',
  // A TypeScript incremental-build cache. Nothing reads it from a fixture and
  // it is invalidated by the first compile anyway.
  'tsconfig.tsbuildinfo',
  // Sprint 1's own gate verdicts. Carrying them forward is the vacuous-pass
  // trap: the delta route asserts that sprint 2 LEAVES design-grounding.json,
  // and a baseline that ships sprint 1's copy satisfies that assertion without
  // sprint 2 ever writing one. The verdicts must be re-earned, not inherited.
  'reviews',
]);

// The delta route builds sprint 2 ON TOP of sprint 1's code, so a planning-only
// tree — every spec present, no product — is not a baseline. It passes every
// artifact check and then fails hours into a live run, which is the expensive
// place to find out. Source files are counted at capture time instead.
const SOURCE_EXTENSIONS = new Set(['.py', '.js', '.jsx', '.ts', '.tsx', '.go', '.rs', '.rb', '.java', '.kt', '.cs', '.php']);
const NON_SOURCE_DIRS = new Set(['specs', 'docs', 'sprint-contracts']);
const MIN_SOURCE_FILES = 3;

// A baseline the delta route cannot use is worse than none — it would fail deep
// inside a live run instead of at capture time.
const REQUIRED = [
  path.join('specs', 'design', 'architecture.md'),
  path.join('specs', 'design', 'component-map.md'),
  path.join('specs', 'design', 'design-traces.json'),
  path.join('specs', 'brd', 'brd-requirements.json'),
];

function parseArgs(argv) {
  const out = { from: null, snapshotOnly: false, resume: false };
  for (let i = 0; i < argv.length; i += 1) {
    if (argv[i] === '--from') out.from = argv[++i];
    else if (argv[i].startsWith('--from=')) out.from = argv[i].slice('--from='.length);
    else if (argv[i] === '--snapshot-only') out.snapshotOnly = true;
    else if (argv[i] === '--resume') out.resume = true;
    else throw new Error(`unknown argument: ${argv[i]}`);
  }
  if (out.from && !fs.existsSync(out.from)) throw new Error(`--from ${out.from} does not exist`);
  return out;
}

function copyTree(src, dest) {
  fs.mkdirSync(dest, { recursive: true });
  let files = 0;
  for (const entry of fs.readdirSync(src, { withFileTypes: true })) {
    if (EXCLUDED.has(entry.name)) continue;
    const from = path.join(src, entry.name);
    const to = path.join(dest, entry.name);
    if (entry.isDirectory()) files += copyTree(from, to);
    else if (entry.isFile()) { fs.copyFileSync(from, to); files += 1; }
  }
  return files;
}

// `out` exists so the capture can be exercised against a scratch directory;
// every caller here uses the committed default.
/** Product source files, ignoring the spec/doc trees and everything excluded. */
function countSourceFiles(dir, top = true) {
  let count = 0;
  let entries;
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch (_) { return 0; }
  for (const entry of entries) {
    if (EXCLUDED.has(entry.name)) continue;
    if (top && entry.isDirectory() && NON_SOURCE_DIRS.has(entry.name)) continue;
    if (entry.isDirectory()) count += countSourceFiles(path.join(dir, entry.name), false);
    else if (SOURCE_EXTENSIONS.has(path.extname(entry.name))) count += 1;
  }
  return count;
}

function snapshot(source, out = OUT_DIR) {
  const missing = REQUIRED.filter((rel) => !fs.existsSync(path.join(source, rel)));
  if (missing.length) {
    throw new Error(
      `${source} is not a usable sprint-1 baseline — missing:\n  ${missing.join('\n  ')}\n`
      + 'The delta route amends a living design; without one it has nothing to amend.',
    );
  }
  const sources = countSourceFiles(source);
  if (sources < MIN_SOURCE_FILES) {
    throw new Error(
      `${source} carries a full spec set but only ${sources} source file(s) — this is a `
      + 'planning-only tree, not a built sprint-1 system.\nThe delta route builds sprint 2 on '
      + "top of sprint 1's code; seeding from specs alone fails hours into a live run.",
    );
  }
  fs.rmSync(out, { recursive: true, force: true });
  const files = copyTree(source, out);
  process.stdout.write(`baseline: ${files} file(s) captured from ${source}\n  -> ${out}\n`);
  return files;
}

const PHASE_LOG = [];
const SESSIONS = [];
let RESUME = false;

// Sessions are persisted so a RESUMED run can still bill the phases it skipped.
// Without this the bill narrows to whatever the LAST process ran: the committed
// sprint-1 baseline was recorded from a resumed run and therefore omitted
// /scaffold and /brd entirely and recorded (freeform) at $0.00, so the ratchet
// was 9% light AND permanently blind to three phases. A baseline that silently
// covers less than the route ran is worse than no baseline.
const SESSION_LOG = path.join(BUILD_DIR, '.claude', 'state', 'e2e-sessions.json');

function rememberSession(sessionId) {
  if (!sessionId || SESSIONS.includes(sessionId)) return;
  SESSIONS.push(sessionId);
  try {
    fs.mkdirSync(path.dirname(SESSION_LOG), { recursive: true });
    fs.writeFileSync(SESSION_LOG, `${JSON.stringify(SESSIONS, null, 2)}\n`);
  } catch (_) { /* the bill degrades to this process's sessions; never fail the run */ }
}

/**
 * Which sessions a run starts from.
 *
 * ONLY a resume inherits. liveBuild() -> freshProject() wipes BUILD_DIR and the
 * session log inside it, but the transcripts those sessions wrote live in
 * ~/.claude/projects/<slug>/ and are never touched — so reading the log on a
 * FRESH run put the previous run's ids into the bill before the wipe, and the
 * baseline recorded both runs at roughly double the real cost. expectPhases
 * cannot catch that: it only sees phases that are MISSING, never billed twice.
 */
function startingSessions(resume, logPath = SESSION_LOG) {
  if (!resume) return [];
  try {
    const ids = JSON.parse(fs.readFileSync(logPath, 'utf8'));
    return Array.isArray(ids) ? ids.filter((id) => typeof id === 'string') : [];
  } catch (_) { return []; /* first run, or an unreadable log */ }
}

function loadRememberedSessions() {
  for (const id of startingSessions(RESUME)) if (!SESSIONS.includes(id)) SESSIONS.push(id);
}

// `/spec` and `/design` are SHAPING phases: they present their load-bearing
// decisions and wait to be answered. That stop is a real control — the decisions
// validator refuses to unlock the renderer unless every load-bearing decision
// records who settled it.
//
// This run is unattended by construction, so it says so. It declares the
// autonomy lane once (see declareLane) and answers the dialogue in a second
// turn in the SAME session, asking for the calls to be recorded as
// `headless-default` — "settled without a human" — rather than `human`. The
// gate still runs and still blocks: a lane relaxes WHICH basis counts, never
// whether one is required, so a phase that settled nothing still fails.
//
// The point of the distinction is the record. An unattended run labelled
// `human` is indistinguishable from one a person actually reviewed; labelled
// `headless-default` it stays legible to whoever reads the decisions file later.
const APPROVAL = 'This is an unattended --auto lane run: there is no human here and no further '
  + 'turns are coming. Settle every open decision on your proposed default, record each '
  + 'load-bearing decision with basis "headless-default" (NOT "human" — no human reviewed '
  + 'these, and the record must say so, and NOT "default-accepted", which the gate rejects), '
  + 'write the decisions file, run its validation gate, and then COMPLETE THE PHASE: '
  + 'dispatch the renderer and expand the decisions into their artifacts. Do not stop at a '
  + '/clear checkpoint — a declared --auto lane suppresses it and there is no human to clear.';

// The sprint-1 baseline has to carry the WHOLE PRD, not just its first
// milestone. `/spec` defaults to scoping a first pass to M1 ("a signed-in
// member can create a link, be redirected by it, and sign out"), which would
// leave out the console — list, delete, /healthz. Sprint 2 then amends FR-4
// (click counts on the list) and FR-5, so a baseline without M2 would make the
// delta meaningless.
const WHOLE_PRD = 'Scope: the ENTIRE PRD in one pass — both milestones M1 and M2, all of '
  + 'FR-1..FR-8 and NFR-1..NFR-6. Do not defer M2 to a later pass.';

/**
 * One phase, one cold session.
 *
 * The harness's own docs are explicit that running the planning commands as
 * separate invocations, clearing between each, is the cheaper route — a phase
 * continued in its predecessor's session ran 47 turns at a 273K average
 * context against ~110K for a fresh one. A new session id is that clear,
 * mechanically.
 */
function phase(label, prompt, budgetUsd, timeoutMs, opts = {}) {
  const sessionId = opts.sessionId || randomUUID();
  const started = Date.now();
  process.stdout.write(`\n=== ${label} ===\n`);
  const res = runClaude(prompt, {
    cwd: BUILD_DIR, model: 'sonnet', pluginDir: PLUGIN_DIR, sessionId,
    budgetUsd, timeoutMs, continueSession: Boolean(opts.continueSession),
  });
  const seconds = Math.round((Date.now() - started) / 1000);
  PHASE_LOG.push({ label, sessionId, exitCode: res.exitCode, seconds });
  rememberSession(sessionId);
  process.stdout.write(`${label}: exit=${res.exitCode} ${seconds}s\n`);
  if (res.sessionLimited) throw new Error(`${label}: ${res.limitMessage}`);
  return sessionId;
}

/**
 * A phase and the artifacts it must produce, skippable on resume.
 *
 * The live phases cost real money and tens of minutes each, so a run that dies
 * in `/design` should not re-pay for `/scaffold` and `/brd`. On resume a phase
 * whose artifacts are already on disk is skipped — but its VALIDATION still
 * runs, so a resume can never inherit an unchecked artifact from an earlier
 * attempt.
 */
function step(opts) {
  const { label, prompt, budgetUsd, timeoutMs, expects = [], validate, approve } = opts;

  // The phase's OWN checks decide whether it is settled — artifacts present and
  // its validator green. Keying on "the file exists" is what let a decisions
  // file that failed its gate look finished on the next resume.
  const check = () => {
    try {
      expect(label, expects);
      if (validate) validate();
      return null;
    } catch (err) {
      return err;
    }
  };

  if (RESUME && expects.length && check() === null) {
    process.stdout.write(`\n=== ${label} (resumed — already settled) ===\n`);
    return;
  }

  const sessionId = phase(label, prompt, budgetUsd, timeoutMs);

  let failure = check();
  // A shaping phase stops to be answered rather than failing. Answer it in its
  // own session and let the same checks judge the result — an approval that
  // produced nothing still fails the phase.
  if (failure && approve) {
    process.stdout.write(`${label}: not settled yet — sending the operator's answer\n  (${failure.message.split('\n')[0]})\n`);
    phase(`${label} (approval)`, approve, budgetUsd, timeoutMs, { sessionId, continueSession: true });
    failure = check();
  }
  if (failure) throw failure;
}

/**
 * Validate a phase's output before paying for the next one.
 *
 * A planning phase that produced nothing still lets the next command start; the
 * failure then surfaces an hour later, in the wrong place. Every phase is
 * checked against the artifacts its own skill promises.
 */
function expect(label, rels) {
  const missing = rels.filter((rel) => !fs.existsSync(path.join(BUILD_DIR, rel)));
  if (missing.length) {
    throw new Error(`${label} did not write:\n  ${missing.join('\n  ')}\n  in ${BUILD_DIR}`);
  }
  process.stdout.write(`${label}: ${rels.length} artifact(s) present\n`);
}

/** Run a harness script against the build; throw with its output on failure. */
function script(name, args, why) {
  try {
    execFileSync('node', [path.join(PLUGIN_DIR, 'scripts', name), ...args],
      { cwd: BUILD_DIR, stdio: 'pipe' });
  } catch (err) {
    const out = `${(err.stdout || '').toString()}${(err.stderr || '').toString()}`.slice(-1500);
    throw new Error(`${why} (${name} exit ${err.status})\n${out}`);
  }
}

/** The human approval a headless run cannot give, through the documented lane. */
function waive(gate) {
  script('plan-approval.js', ['waive', '--phase', gate, '--lane', '--auto', '--root', BUILD_DIR],
    `could not waive the ${gate} gate`);
  process.stdout.write(`${gate} gate: waived (headless lane)\n`);
}

function readJson(...rel) {
  try { return JSON.parse(fs.readFileSync(path.join(BUILD_DIR, ...rel), 'utf8')); }
  catch (_) { return null; }
}

/**
 * Build sprint 1 the way the harness documents: scaffold, then /brd -> /spec ->
 * /design -> /test as separate invocations, then /auto. Every phase's output is
 * validated before the next one is paid for.
 */
/**
 * Declare this run's autonomy lane, once.
 *
 * `record-run.js` writes `current-lane` only for an invocation that actually
 * declares a lane, and a phase command no longer overwrites it — so a lane
 * declared here survives `/brd`, `/spec`, `/design` and `/test`. That is what
 * lets the decisions gates corroborate the `--lane --auto` this run claims,
 * instead of reading a command name and refusing it.
 *
 * Declaring it is the honest move, not a bypass: the run genuinely has no human
 * in it, and every gate still runs against that declaration.
 */
function declareLane() {
  const stateDir = path.join(BUILD_DIR, '.claude', 'state');
  fs.mkdirSync(stateDir, { recursive: true });
  fs.writeFileSync(path.join(stateDir, 'current-lane'), 'auto');
  process.stdout.write('lane: declared --auto (unattended run)\n');
}

function liveBuild() {
  const prd = resolvePrd('sprint1');
  process.stdout.write(`baseline: live sprint-1 build from ${prd}\n  in ${BUILD_DIR}\n`);
  if (RESUME) process.stdout.write('resuming: phases whose artifacts exist will be skipped\n');
  else freshProject(BUILD_DIR, prd);

  // ── Phase 0: scaffold ──────────────────────────────────────────────────
  step({
    label: 'scaffold',
    prompt: '/scaffold --yes a Python FastAPI + Next.js shortlink service from prd.md; '
      + 'API and web surface; Postgres 16; no team integrations, no tracker, no framework packs',
    budgetUsd: '5.00',
    timeoutMs: 900000,
    expects: ['project-manifest.json'],
  });
  declareLane();

  // ── Phase 1: /brd ──────────────────────────────────────────────────────
  step({
    label: 'brd',
    prompt: '/brd --prd prd.md',
    budgetUsd: '6.00',
    timeoutMs: 1200000,
    expects: [
      path.join('specs', 'brd', 'brd.md'),
      path.join('specs', 'brd', 'brd-requirements.json'),
    ],
    validate: () => {
      const grounding = readJson('specs', 'reviews', 'brd-grounding.json');
      if (grounding && grounding.status === 'fail') {
        throw new Error(`brd grounding failed: ${JSON.stringify(grounding).slice(0, 400)}`);
      }
      // The PRD is the oracle: every requirement it declares must reach the
      // spine, and the spine must not carry one the PRD never asked for. A
      // count alone cannot tell "all 14 captured" from "8 captured, 6 invented".
      const spine = readJson('specs', 'brd', 'brd-requirements.json') || [];
      const gap = spineGap(prd, spine);
      if (gap.missing.length || gap.invented.length) {
        throw new Error(
          `brd spine does not match the PRD.\n  missing: ${gap.missing.join(', ') || '(none)'}`
          + `\n  invented: ${gap.invented.join(', ') || '(none)'}`,
        );
      }
      process.stdout.write(`brd: ${spine.length} requirement(s), matching the PRD exactly\n`);
      waive('brd');
    },
  });

  // ── Phase 2: /spec — shaping AND render in one invocation ──────────────
  // Two invocations used to be required: without a declared lane the decisions
  // gate prints a CHECKPOINT telling the operator to /clear and re-enter with
  // --render-only, because the shaping dialogue leaves ~284K of conversation
  // the render does not need. A declared lane suppresses that checkpoint (the
  // renderer forks to its own context anyway), so the phase completes in one
  // call and this run stops paying for a second cold session that re-reads the
  // BRD and the decisions file only to fork the same renderer.
  step({
    label: 'spec',
    prompt: `/spec\n\n${WHOLE_PRD}`,
    approve: APPROVAL,
    budgetUsd: '14.00',
    timeoutMs: 2700000,
    expects: [
      path.join('specs', 'decisions', 'spec-decisions.json'),
      path.join('specs', 'stories', 'dependency-graph.md'),
      'features.json',
    ],
    validate: () => {
      script('validate-spec-decisions.js',
        ['--root', BUILD_DIR, '--rendering', '--lane', '--auto'],
        'the spec decisions file did not pass its own validator');
      const stories = fs.readdirSync(path.join(BUILD_DIR, 'specs', 'stories'))
        .filter((f) => /^E\d+-S\d+\.md$/.test(f));
      if (!stories.length) throw new Error('spec wrote no story files');
      process.stdout.write(`spec: ${stories.length} story file(s)\n`);
      waive('spec');
    },
  });

  // ── Phase 3: /design — shaping AND render in one invocation ────────────
  step({
    label: 'design',
    prompt: '/design',
    approve: APPROVAL,
    budgetUsd: '16.00',
    timeoutMs: 3000000,
    // The rendered design set IS the baseline the sprint route later proves was
    // amended rather than regenerated — REQUIRED names those files.
    expects: [
      path.join('specs', 'decisions', 'design-decisions.json'),
      ...REQUIRED.filter((rel) => rel.startsWith(path.join('specs', 'design'))),
    ],
    validate: () => {
      script('validate-design-decisions.js',
        ['--root', BUILD_DIR, '--rendering', '--lane', '--auto'],
        'the design decisions file did not pass its own validator');
      waive('design');
    },
  });

  // ── Phase 4: /test ─────────────────────────────────────────────────────
  step({
    label: 'test',
    prompt: '/test --plan-only',
    approve: APPROVAL,
    budgetUsd: '8.00',
    timeoutMs: 1500000,
    expects: [
      path.join('specs', 'test_artefacts', 'verification-matrix.json'),
      path.join('specs', 'test_artefacts', 'test-traces.json'),
    ],
    validate: () => {
      waive('test');
      script('bundle-write.js', [], 'bundle-write failed — stories would reach /auto with no execution contract');
    },
  });

  // ── Phase 5: /auto ─────────────────────────────────────────────────────
  // No `expects` gate: the build is judged by the project's own suite, not by a
  // file existing, so this phase is never skipped on resume.
  (phase('auto', '/auto\n\nImplement every open group until the project\'s own test '
    + 'suite passes. Do not replan.', '60.00', 5400000));

  let suite = runManifestSuite(BUILD_DIR, 1200000);
  process.stdout.write(`suite after /auto: status=${suite.status} ran=${JSON.stringify(suite.ran)}`
    + `${suite.skipped && suite.skipped.length ? ` skipped=${suite.skipped.join(',')}` : ''}\n`);
  if (suite.status !== 0) {
    process.stdout.write('not green — one bounded resume\n');
    (phase('auto-resume', '/auto\n\nContinue the open groups until the project\'s own '
      + 'test suite passes. Do not replan.', '40.00', 3600000));
    suite = runManifestSuite(BUILD_DIR, 1200000);
    process.stdout.write(`suite after resume: status=${suite.status}\n`);
  }

  const bill = billRoute(BUILD_DIR, { sessionIds: SESSIONS });
  process.stdout.write(`\n${formatBill('sprint1-baseline', bill)}\n`);
  process.stdout.write(`\nphases:\n${PHASE_LOG.map((p) => `  ${p.label}: exit=${p.exitCode} ${p.seconds}s`).join('\n')}\n`);
  // Every phase the route runs must appear in the bill, or the baseline is
  // recorded blind to the rest — see writeBaseline.
  writeBaseline('sprint1-baseline', bill, undefined, {
    expectPhases: ['scaffold', 'brd', 'spec', 'design', 'test', 'auto'],
  });

  if (suite.status !== 0) {
    throw new Error(
      `sprint-1 build did not leave a green suite (status ${suite.status}). `
      + `Not capturing a red baseline.\n${suite.out}`,
    );
  }
  return BUILD_DIR;
}

function main(argv) {
  const opts = parseArgs(argv);
  RESUME = opts.resume;
  // ONLY on resume. liveBuild() -> freshProject() wipes BUILD_DIR (and the
  // session log inside it), but the transcripts those sessions wrote live in
  // ~/.claude/projects/<slug>/ and are never touched — so loading the log
  // unconditionally put the PREVIOUS run's session ids into SESSIONS before the
  // wipe, and a fresh run then billed both runs and recorded a roughly doubled
  // baseline. expectPhases cannot see that: it only catches phases that are
  // MISSING, never a phase billed twice.
  loadRememberedSessions();
  const source = opts.from ? path.resolve(opts.from)
    : (opts.snapshotOnly ? BUILD_DIR : liveBuild());
  snapshot(source);
  process.stdout.write('Commit the captured tree so the /sprint route can seed from it.\n');
}

if (require.main === module) {
  try {
    main(process.argv.slice(2));
  } catch (err) {
    process.stderr.write(`${err.message}\n`);
    process.exit(1);
  }
}

module.exports = {
  EXCLUDED, REQUIRED, OUT_DIR, MIN_SOURCE_FILES,
  copyTree, snapshot, parseArgs, countSourceFiles, startingSessions,
};
